function simplifyPath(path: string): string {
  // Стек имён каталогов от корня до текущего
  const stack: string[] = [];

  // Разбиваем по '/': пустые части появляются из-за '//' и слешей по краям
  for (const part of path.split('/')) {
    if (part === '' || part === '.') {
      // Пустая часть или '.' — остаёмся в текущем каталоге
      continue;
    }
    if (part === '..') {
      // Поднимаемся на уровень выше; из корня подняться нельзя — pop на пустом стеке ничего не делает
      stack.pop();
    } else {
      // Обычное имя (в том числе '...') — спускаемся в каталог
      stack.push(part);
    }
  }

  // Собираем канонический путь; для пустого стека получится "/"
  return '/' + stack.join('/');
}

// Время: O(n) — один проход по строке
// Память: O(n) — части пути и стек
